={
  "query": "{{ $fromAI('searchQuery', 'Praezise Suchanfrage, z. B. Spielername kombiniert mit dem gesuchten Detail (Marktwert/Vertrag/Verletzung/Transfer News)', 'string') }}",
  "search_depth": "advanced",
  "include_answer": true,
