}

parameters.inputSchema:
{
  "type": "object",
  "required": ["club", "contract", "contractEndDate", "marketValue", "marketValueMEUR", "injuries", "currentSituation", "news", "transferLikelihoodNotes", "evidence"],
  "properties": {
    "club": {"type": ["string", "null"]},
    "contract": {"type": ["string", "null"]},
    "contractEndDate": {"type": ["string", "null"], "description": "ISO-Datum YYYY-MM-DD des recherchierten Vertragsendes oder null."},
    "marketValue": {"type": ["string", "null"]},
    "marketValueMEUR": {"type": ["number", "null"], "description": "Marktwert in Mio. EUR oder null."},
    "injuries": {"type": ["string", "null"]},
    "currentSituation": {"type": ["string", "null"]},
    "news": {"type": "array", "items": {"type": "string"}},
    "transferLikelihoodNotes": {"type": ["string", "null"]},
    "evidence": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["fact", "claim", "source", "url", "timestamp", "confidence"],
        "properties": {
          "fact": {"type": "string", "enum": ["club", "contract", "marketValue", "injuries", "currentSituation", "transferLikelihoodNotes", "news"]},
          "claim": {"type": "string"},
          "source": {"type": "string"},
          "url": {"type": "string"},
          "timestamp": {"type": ["string", "null"]},
          "confidence": {"type": "number"}
        }
      }
    },
    "confidence": {"type": ["number", "null"]}
  }
}

parameters.jsCode:
const trigger = $('Wenn von anderem Workflow aufgerufen').first().json;
const candidate = trigger.researchCandidateName;
const raw = $input.item.json;
const out = (raw.output && typeof raw.output === 'object') ? raw.output : raw;
const now = new Date().toISOString();

const cleanText = (value) => typeof value === 'string' ? value.trim().replace(/\s+/g, ' ') : '';
const sameText = (claim, value) => cleanText(claim) === cleanText(value);
const claimHasDate = (claim, isoDate) => {
  if (!isoDate) return true;
  const text = cleanText(claim);
  if (text.includes(isoDate)) return true;
  const parts = isoDate.split('-');
  if (parts.length !== 3) return false;
  return text.includes(`${parts[2]}.${parts[1]}.${parts[0]}`);
};
const claimNumber = (claim) => {
  const match = cleanText(claim).match(/(-?\d+(?:[.,]\d+)?)/);
  return match ? Number(match[1].replace(',', '.')) : null;
};

const news = Array.isArray(out.news) ? out.news.filter((entry) => typeof entry === 'string' && entry.trim().length > 0).map((entry) => entry.trim()) : [];
const club = cleanText(out.club) || null;
const contract = cleanText(out.contract) || null;
const marketValue = cleanText(out.marketValue) || null;
const injuries = cleanText(out.injuries) || null;
const currentSituation = cleanText(out.currentSituation) || null;
const transferLikelihoodNotes = cleanText(out.transferLikelihoodNotes) || null;
const contractEndDateRaw = cleanText(out.contractEndDate) || null;
const contractEndDate = (contractEndDateRaw && /^\d{4}-\d{2}-\d{2}$/.test(contractEndDateRaw) && !Number.isNaN(Date.parse(contractEndDateRaw))) ? contractEndDateRaw : null;
const marketValueMEUR = (typeof out.marketValueMEUR === 'number' && Number.isFinite(out.marketValueMEUR)) ? out.marketValueMEUR : null;

const allowedFacts = new Set(['club','contract','marketValue','injuries','currentSituation','transferLikelihoodNotes','news']);
const evidence = (Array.isArray(out.evidence) ? out.evidence : []).map((entry) => {
  if (!entry || typeof entry !== 'object') return null;
  const fact = cleanText(entry.fact);
  const claim = cleanText(entry.claim);
  const source = cleanText(entry.source);
  const url = cleanText(entry.url);
  if (!allowedFacts.has(fact) || !claim || !source || !/^https?:\/\//i.test(url)) return null;
  let confidence = typeof entry.confidence === 'number' && Number.isFinite(entry.confidence) ? entry.confidence : 0;
  confidence = Math.max(0, Math.min(1, confidence));
  const parsedTimestamp = typeof entry.timestamp === 'string' && entry.timestamp.trim() && !Number.isNaN(Date.parse(entry.timestamp))
    ? new Date(entry.timestamp).toISOString()
    : now;
  return {fact, claim, source, url, timestamp: parsedTimestamp, confidence};
}).filter(Boolean);

const requiredEvidenceFacts = [];
const requireEvidence = (label, matcher) => {
  if (!evidence.some(matcher)) requiredEvidenceFacts.push(label);
};
if (club) requireEvidence('club', (entry) => entry.fact === 'club' && sameText(entry.claim, club));
if (contract) requireEvidence('contract', (entry) => entry.fact === 'contract' && sameText(entry.claim, contract));
if (contractEndDate) requireEvidence('contractEndDate', (entry) => entry.fact === 'contract' && claimHasDate(entry.claim, contractEndDate));
if (marketValue) requireEvidence('marketValue', (entry) => entry.fact === 'marketValue' && sameText(entry.claim, marketValue));
if (marketValueMEUR !== null) requireEvidence('marketValueMEUR', (entry) => entry.fact === 'marketValue' && claimNumber(entry.claim) === marketValueMEUR);
if (injuries) requireEvidence('injuries', (entry) => entry.fact === 'injuries' && sameText(entry.claim, injuries));
if (currentSituation) requireEvidence('currentSituation', (entry) => entry.fact === 'currentSituation' && sameText(entry.claim, currentSituation));
if (transferLikelihoodNotes) requireEvidence('transferLikelihoodNotes', (entry) => entry.fact === 'transferLikelihoodNotes' && sameText(entry.claim, transferLikelihoodNotes));
const uncoveredNews = news.filter((headline) => !evidence.some((entry) => entry.fact === 'news' && sameText(entry.claim, headline)));

const hasCoreFacts = Boolean(club) && Boolean(contract) && Boolean(marketValue) && Boolean(injuries) && news.length > 0;
const provenanceComplete = evidence.length > 0 && requiredEvidenceFacts.length === 0 && uncoveredNews.length === 0;
const uncertain = !hasCoreFacts || !provenanceComplete;
const confidence = evidence.length ? evidence.reduce((sum, entry) => sum + entry.confidence, 0) / evidence.length : 0;
const sources = [...new Set(evidence.map((entry) => entry.source))];
const source = sources.length === 1 ? sources[0] : `${sources.length} Quellen – siehe evidence`;
const provenanceIssues = [
  ...requiredEvidenceFacts.map((fact) => `keine zum Feldwert passende Evidence fuer ${fact}`),
  ...uncoveredNews.map((headline) => `keine zum News-Text passende Evidence fuer: ${headline}`)
];

const researchResult = {
  candidate, club, contract, contractEndDate, marketValue, marketValueMEUR,
  injuries, currentSituation, transferLikelihoodNotes, news, evidence,
  source: evidence.length ? source : 'Websuche (keine belastbare Evidence persistiert)',
  timestamp: now,
  confidence: uncertain ? 0 : Number(confidence.toFixed(3)),
  uncertain,
  uncertaintyReason: uncertain
    ? `Websuche konnte den erforderlichen Due-Diligence-Vertrag nicht vollstaendig und wertgebunden belegen.${provenanceIssues.length ? ' ' + provenanceIssues.join('; ') : ''}`
    : null
};
return [{json:{...trigger,researchRuntimeBatchId:trigger.researchBatchId,researchRuntimeCandidate:candidate,researchRuntimeStatus:uncertain?'uncertain':'success',researchRuntimePayload:JSON.stringify(researchResult),researchRuntimeCompletedAt:now}}];

const trigger = $('Wenn von anderem Workflow aufgerufen').first().json;
const candidate = trigger.researchCandidateName || 'unbekannter Kandidat';
const current = $input.item.json || {};
const reason = (current.error && (current.error.message || current.error)) || 'Recherche-Agent konnte kein Ergebnis liefern.';
const now = new Date().toISOString();
const researchResult = {candidate,club:null,contract:null,contractEndDate:null,marketValue:null,marketValueMEUR:null,injuries:null,currentSituation:null,transferLikelihoodNotes:null,news:[],evidence:[],source:'Websuche fehlgeschlagen (keine Quelle verfuegbar)',timestamp:now,confidence:0,uncertain:true,uncertaintyReason:String(reason)};
return [{json:{...trigger,researchRuntimeBatchId:trigger.researchBatchId,researchRuntimeCandidate:candidate,researchRuntimeStatus:'agent_error',researchRuntimePayload:JSON.stringify(researchResult),researchRuntimeCompletedAt:now}}];
